s={(2,5),(3,3),(3,4),(3,5),(3,7),(4,3),(5,3),(5,4),(5,5),(5,6),(6,2),(6,7)}
t={(2,5),(3,2),(3,3),(4,3),(4,5),(4,6),(5,3),(5,5),(6,3),(6,4),(6,5),(7,2)}
# coordinate transforms translate to bounding box for all 8 dihedral rotations
for name,f in [('id',lambda r,c:(r,c)),('rot90',lambda r,c:(c,-r)),('rot180',lambda r,c:(-r,-c)),('rot270',lambda r,c:(-c,r)),('flip_h',lambda r,c:(r,-c)),('flip_v',lambda r,c:(-r,c)),('diag',lambda r,c:(c,r)),('anti',lambda r,c:(-c,-r))]:
 q=[f(r,c) for r,c in s]; mr=min(r for r,c in q); mc=min(c for r,c in q); q={(r-mr,c-mc) for r,c in q}
 mt=min(r for r,c in t); mct=min(c for r,c in t); tt={(r-mt,c-mct) for r,c in t}
 print(name, q==tt, len(q&tt), sorted(q), sorted(tt))
